from pathlib import Path
from urllib.parse import quote
from .dashboard import esc
SCRIPT=Path(__file__).with_name('console.js').read_text()+'\n'+Path(__file__).with_name('console_editor.js').read_text(encoding='utf-8')


def section(agent,csrf,data):
    info=data.get('console')
    if data.get('agent_platform')=='portal':return ''
    body='<section class="server" id="remote-console" data-protected-pane data-shell="'+esc((info or {}).get('shell',''))+'" data-url="/api/servers/'+esc(quote(agent,safe=''))+'/console" data-agent="'+esc(agent)+'"><h2>Мини-консоль</h2>'
    if not info:return body+'<p class="muted">Обновите агент для поддержки консоли.</p></section>'
    body+='<p>Оболочка: '+esc(info.get('shell'))+' · Пользователь службы: '+esc(info.get('identity'))+'</p><p class="muted">Один запуск за раз: можно отправить несколько команд, каждую с новой строки. Вывод появляется по мере выполнения после получения агентом задания. Рабочая папка — каталог конфигурации агента. Все строки одного запуска выполняются в одной оболочке: cd и переменные между ними сохраняются. Между отдельными запусками состояние не сохраняется. Лимит времени и вывода общий на весь блок. Команды и вывод сохраняются в истории панели.</p>'
    if not info.get('streaming'):body+='<p class="muted">Обновите агент для живого вывода; текущая версия отправляет результат после завершения.</p>'
    if not info.get('enabled'):body+='<p class="notice">Консоль выключена на агенте. Включите allow_remote_console локально и перезапустите службу. См. deploy/CONSOLE.md.</p>'
    else:
        body+='<form id="console-form"><input type="hidden" name="csrf" value="'+esc(csrf)+'"><label for="console-command">Команды</label><div class="console-editor"><textarea id="console-command" name="command" rows="4" maxlength="4000" required spellcheck="false" autocomplete="off" autocapitalize="off" autocorrect="off" aria-autocomplete="list" aria-controls="console-completions" aria-expanded="false" aria-describedby="console-editor-help" placeholder="'+('Get-Service | Select-Object -First 10' if info.get('shell')=='powershell' else 'uptime; df -h /')+'"></textarea><div id="console-completions" class="console-completions" role="listbox" aria-label="Подсказки команд" hidden></div></div><div class="console-editor-tools"><button type="button" id="console-show-hints">Подсказки</button><span class="muted" id="console-editor-count" role="status"></span></div><p class="muted" id="console-editor-help">Enter — новая строка · Ctrl+Enter — выполнить блок · Ctrl+Пробел — подсказки · ↑/↓ — выбор · Tab/Enter — вставить подсказку · Esc — закрыть. Встроенная справка не проверяет наличие команды на сервере и ничего не запускает.</p><label>Лимит времени<select name="timeout"><option value="15">15 секунд</option><option value="30" selected>30 секунд</option><option value="60">60 секунд</option></select></label><label class="check"><input type="checkbox" name="confirmation" required> Выполнить на '+esc(agent)+' с правами указанной службы</label><button type="submit">Выполнить</button><button type="button" id="console-review" hidden>Результат проверен локально — разрешить новую команду</button></form>'
    if info.get('enabled'):
        body+='<form id="console-input-form" hidden><h3>Ответ работающей команде</h3><label>Строка ввода<input name="stdin" maxlength="1024" autocomplete="off" placeholder="Ответ и Enter"></label><button type="submit">Отправить строку</button><button type="button" data-console-eof>Завершить ввод (EOF)</button><button type="button" data-console-cancel>Остановить команду</button><p class="muted">Ответ передаётся как обычный текст. Защищённый ввод паролей не поддерживается.</p></form>'
    body+='<p id="console-message" role="status" aria-live="polite"></p><div class="searchbar"><button type="button" id="console-clear">Очистить</button><button type="button" id="console-archive">Показать всю историю</button></div><p class="muted" id="console-scope">История за последний час</p><div id="console-history"></div><button type="button" id="console-more" hidden>Показать ещё</button></section><script data-protected-script>'+SCRIPT+'</script>'
    return body
